      // eslint-disable-next-line no-console
      console.log(`FRAME mean=${mean.toFixed(2)}ms median=${(deltas[Math.floor(deltas.length / 2)] ?? 0).toFixed(2)}ms p95=${(deltas[Math.floor(deltas.length * 0.95)] ?? 0).toFixed(2)}ms fps=${(1000 / mean).toFixed(1)}`)
      samples.current = []
    }
  })
  return null
}

