(async () => {
  const canvas = document.querySelector('canvas')
  const rect = canvas.getBoundingClientRect()
  const hit = () => document.querySelector('[class*=hoverLabel]')
  const move = (x, y) => {
    const event = new PointerEvent('pointermove', {
      clientX: x, clientY: y, bubbles: true, cancelable: true,
      pointerId: 1, pointerType: 'mouse', isPrimary: true, buttons: 0,
    })
    Object.defineProperty(event, 'offsetX', { value: x - rect.left })
    Object.defineProperty(event, 'offsetY', { value: y - rect.top })
    canvas.dispatchEvent(event)
  }
  for (let y = rect.top + 100; y < rect.bottom - 160; y += 11) {
    for (let x = rect.left + 100; x < rect.right - 100; x += 11) {
      move(x, y)
      if (hit()) {
        await new Promise(resolve => setTimeout(resolve, 900))
        if (hit()) return `hover at ${Math.round(x)},${Math.round(y)}: ${hit().textContent}`
      }
    }
  }
  return 'no hover'
})()

