// A stand-in feed that serves the real NodeGoat review mid-run: three
// departments have released their findings, three are still pending, and the
// certificate is not issued. Everything else is proxied to the live feed.
import { createServer } from 'node:http'

const UPSTREAM = 'http://localhost:4711'
const RUN = 'NodeGoat-2026-09-19T20-49-35'
const RELEASED = new Set(['secrets', 'injection', 'access'])

const headers = {
  'access-control-allow-origin': '*',
  'content-type': 'application/json',
  'cache-control': 'no-store',
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url ?? '/', 'http://localhost')
  try {
    if (url.pathname === '/runs') {
      const runs = await (await fetch(`${UPSTREAM}/runs`)).json()
      const patched = runs.map(run => (run.id === RUN
        ? { ...run, status: 'running', endedAt: undefined }
        : run))
      response.writeHead(200, headers)
      response.end(JSON.stringify(patched))
      return
    }
    if (url.pathname.startsWith('/safety/')) {
      const detail = await (await fetch(`${UPSTREAM}${url.pathname}`)).json()
      const findings = detail.findings.filter(finding => RELEASED.has(String(finding.id).split('-')[0]))
      const departments = detail.departments.map(department => (RELEASED.has(department.id)
        ? { ...department, certified: false }
        : { ...department, status: 'pending', certified: false, findings: 0 }))
      const counts = { critical: 0, high: 0, medium: 0, low: 0, info: 0 }
      for (const finding of findings) counts[finding.severity] += 1
      response.writeHead(200, headers)
      response.end(JSON.stringify({
        ...detail,
        findings,
        departments,
        certificate: { ...detail.certificate, verified: false, counts, unverified: [] },
      }))
      return
    }
    const upstream = await fetch(`${UPSTREAM}${url.pathname}${url.search}`)
    response.writeHead(upstream.status, {
      ...headers,
      'content-type': upstream.headers.get('content-type') ?? 'application/json',
    })
    response.end(Buffer.from(await upstream.arrayBuffer()))
  } catch (error) {
    response.writeHead(500, headers)
    response.end(JSON.stringify({ error: String(error) }))
  }
})

server.listen(4712, () => console.log('running-feed on http://localhost:4712'))

