/* Labels the code city anchors in 3D through drei's `Html`. */

.districtLabel {
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.08em;
  color: rgba(186, 202, 230, 0.92);
  background: rgba(4, 6, 11, 0.66);
  border: 1px solid rgba(122, 152, 205, 0.14);
  border-left: 2px solid currentColor;
  border-radius: 3px;
  padding: 1px 6px 1px 5px;
  text-shadow: 0 0 10px rgba(4, 6, 11, 0.9);
